arguments.new_str:
using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: HasIndex is no longer silently ignored; it throws in EF Core 9.
        // Remove HasIndex as Cosmos DB does not support secondary indexes via EF Core.

        // Breaking change 2: Discriminator property renamed from "Discriminator" to "$type".
        // To keep reading existing documents that use "Discriminator", explicitly configure it.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 3: Id format changed from "EntityType|Key" to just "Key".
        // To keep reading existing documents with "Blog|1" format, set id factory or
        // use HasDiscriminatorInJsonId to preserve the old composite id format.
        modelBuilder.Entity<Blog>().HasDiscriminatorInJsonId();
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

