}

arguments.new_str:
class SyncJob
{
    void Run(BlogContext context)
    {
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        // Breaking change 4: EF Core 9 Cosmos uses optimistic concurrency with etags by default.
        // SaveChanges may throw DbUpdateConcurrencyException if documents were modified externally.
        context.SaveChanges();
    }

    // Breaking change 5: Raw SQL queries using c.Discriminator must be updated
    // if you did NOT configure HasDiscriminator("Discriminator") (we did, so existing
    // queries like SELECT * FROM c WHERE c.Discriminator = 'Blog' continue to work).
    // If using the new default, the query would need to be:
    //   SELECT * FROM c WHERE c["$type"] = 'Blog'
}

